def refer_message(reasons: list[str], lang: str) -> str:
    rs = [r for r in reasons if r in WHY] or ["out_of_scope"]
    extra = "\n".join(EXTRA[r][lang] for r in rs if r in EXTRA)
    return REFER[lang].format(why="; ".join(WHY[r][lang] for r in rs[:2]), extra=extra)


def crisis_message(lang: str) -> str:
    return CRISIS[lang]


def caution_banner(reasons: list[str], lang: str) -> str | None:
    why = list(dict.fromkeys(CAUTION_WHY[r][lang] for r in reasons if r in CAUTION_WHY))
    return CAUTION[lang].format(why=", ".join(why)) if why else None
